// Client-side: when a player/monster unit enters a hit/death anim mode (player modes 0/4/0x13, monster modes 0/3/0xd), spawns the appropriate elemental-hit overlay graphic on the unit based on the high nibble of dwLastHitClass (provided the low nibble is also set). Maps element class 0x20->fire_hit, 0x30->ice_explode, 0x40->lightning, 0x10->doubledamage1, 0x70->bash, 0x80->hit_thorns, 0x90->sanctuaryknockback via GFX_AddOverlayToUnit. Visual only; no-op for other unit types or non-hit modes.
void __fastcall UNITMODE_ShowElementalHitOverlay(D2UnitStrc * pUnit, int32_t nAnimMode) {
    uint32_t nElementMask;
    bool bIsHitMode;
    if (!pUnit) {
      return;
    }
    if (pUnit->eUnitType == UNIT_PLAYER) {
      if (!nAnimMode || nAnimMode == 4) {
        goto add_hit_overlay;
      }

      bIsHitMode = nAnimMode == 0x13;
    } else {
      if (pUnit->eUnitType != UNIT_MONSTER) {
        return;
      }
      if (!nAnimMode || nAnimMode == 3) {
        goto add_hit_overlay;
      }

      bIsHitMode = nAnimMode == 0xd;
    }
    if (!bIsHitMode) {
      return;
    }

    add_hit_overlay:
    nElementMask = pUnit->dwLastHitClass & 0xf0;
    if (!(nElementMask && pUnit->dwLastHitClass & 0xf)) {
      return;
    }
    if (nElementMask == 0x20) {
      Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_fire_hit, 2, 0, 0, 0, 0, 0);
      return;
    }
    if (nElementMask == 0x30) {
      Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_ice_explode, 2, 0, 0, 0, 0, 0);
      return;
    }
    if (nElementMask == 0x40) {
      Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_lightning, 2, 0, 0, 0, 0, 0);
      return;
    }
    if (nElementMask == 0x10) {
      Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_doubledamage1, 2, 0, 0, 0, 0, 0);
      return;
    }
    if (nElementMask == 0x70) {
      Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_bash, 2, 0, 0, 0, 0, 0);
      return;
    }
    if (nElementMask == 0x80) {
      Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_hit_thorns, 2, 0, 0, 0, 0, 0);
      return;
    }
    if (nElementMask != 0x90) {
      return;
    }

    Engine::Gfx::GFX_AddOverlayToUnit(pUnit, OVERLAY_sanctuaryknockback, 2, 0, 0, 0, 0, 0);
}

